package main

import (
	"slices"
	"strings"
	"testing"
)

func TestTheOutputCensusReadsNamesAndHeaders(t *testing.T) {
	files := map[string]string{
		"a/table_gen.json":          "{}\n",
		"a/registry.gen.ts":         "export {};\n",
		"a/manifest.generated.json": "{}\n",
		"a/code.go":                 "// Code generated by tool. DO NOT EDIT.\n\npackage a\n",
		"a/page.md":                 "# Page\n\n<!-- Generated by x_test.go. Do not edit by hand. -->\n",
		"a/note.json":               "{\n  \"note\": \"Generated from the surface by `go test`; do not edit by hand.\"\n}\n",
		"a/types.ts":                "/**\n * This file was auto-generated by openapi-typescript.\n */\n",
		"a/schema.json":             "{\"$comment\": \"Written by tools/gen-x from the registry; do not edit.\"}\n",
		"a/doc.go":                  "// Everything here apart from this file is generated — do not edit.\npackage a\n",
		"a/handbook.md":             "Once it has been sent, you do not edit it.\n",
		"a/deep.md":                 strings.Repeat("line\n", headLines) + "<!-- Generated by x. Do not edit by hand. -->\n",
	}
	root := t.TempDir()
	writeFiles(t, root, files)
	var tracked []string
	for path := range files {
		tracked = append(tracked, path)
	}
	slices.Sort(tracked)
	got, err := generatedOutputs(root, tracked)
	if err != nil {
		t.Fatal(err)
	}
	want := []string{"a/code.go", "a/manifest.generated.json", "a/note.json", "a/page.md", "a/registry.gen.ts",
		"a/schema.json", "a/table_gen.json", "a/types.ts"}
	if !slices.Equal(got, want) {
		t.Errorf("census = %v, want %v", got, want)
	}
}

func TestAHeaderThatNamesATaggedTestIsAttributedToIt(t *testing.T) {
	root := t.TempDir()
	writeFiles(t, root, map[string]string{
		"roles.json": "{\n  \"note\": \"Generated by TestTheRolesArePublished (pkg/roles). Do not edit by hand.\"\n}\n",
	})
	for tests, want := range map[string]bool{"TestTheRolesArePublished": true, "TestTheRoles": false} {
		got, err := writtenByOneOf(root, "roles.json", map[string]bool{tests: true})
		if err != nil {
			t.Fatal(err)
		}
		if got != want {
			t.Errorf("attributed to %s = %v, want %v", tests, got, want)
		}
	}
}
